-- 0071_tutorial_registry_seed.sql
--
-- F18 (S12): seed a registry row for every Appendix A tutorial key, so the SA-13 library and
-- check-tutorials agree with the frozen key list in src/lib/tutorialKeys.json. The rows are
-- idempotent (on conflict do nothing) and M2-safe to re-apply; a later recorder run fills media_path
-- and generated_at against a live deployment.
--
-- The key list is the same 85 keys the JSON registry holds. media_path points at the placeholder GIF
-- the recorder writes under public/tutorials/<key>.gif; the player serves /<media_path>.

on conflict (key) do nothing;
